INSERT INTO `ai_knowledge` (`id`, `question`, `answer`, `category`, `hit_count`, `create_time`, `update_time`) VALUES (1,'如何修改密码？','修改密码步骤：1.登录个人中心；2.点击账号安全；3.输入原密码和新密码；4.提交保存。','账号问题',64,'2026-11-10 03:44:04','2026-11-18 10:14:11'),(2,'订单多久发货？','普通商品下单后48小时内发货，预售商品按预售页面标注时间发货，节假日顺延。','订单问题',30,'2026-11-10 03:44:04','2026-11-18 04:05:29'),(3,'如何申请退款？','退款申请步骤：1.进入我的订单；2.找到对应订单点击申请退款；3.选择退款原因；4.提交审核，审核通过后3-7个工作日到账。','退款问题',132,'2026-11-10 03:44:04','2026-11-18 12:09:17'),(4,'商品质量有问题怎么办？','若收到商品存在质量问题，请在收货后7天内联系在线客服，提供商品照片和订单号，客服将协助办理退换货。','售后问题',22,'2026-11-10 03:44:04','2026-11-18 02:58:49'),(7,'订单多久发货','普通图书下单付款后 48 小时内发货，预售商品按商品页标注时间发货，节假日顺延。可在订单管理中查看订单状态，1 表示待发货、2 表示已发货。','订单问题',136,'2026-11-11 06:23:49','2026-11-18 12:09:20'),(8,'如何查询订单状态','进入「业务管理 - 订单管理」，可按订单号、收货人、状态筛选。状态含义：0 待付款、1 待发货、2 已发货、3 已完成、4 已退款。','订单问题',63,'2026-11-11 06:23:49','2026-11-18 12:09:20'),(9,'如何申请退款','在订单管理中找到对应订单，联系客服提交退款申请；审核通过后 3-7 个工作日原路退回，订单状态会变为 4（已退款）。','订单问题',79,'2026-11-11 06:23:49','2026-11-18 12:09:17'),(10,'如何查询图书库存','进入「业务管理 - 图书管理」，可按书名、作者、ISBN、分类筛选，列表中的「库存」列即为当前可售数量。','图书问题',52,'2026-11-11 06:23:49','2026-11-18 12:09:20'),(11,'图书如何上架下架','在图书管理中编辑对应图书，把「状态」改为 1（上架）或 0（下架）后保存即可。下架的图书不再对外展示。','图书问题',66,'2026-11-11 06:23:49','2026-11-18 03:42:30');
