-- Dumping data for table `biz_book_chunk`
--

/*!40000 ALTER TABLE `biz_book_chunk` DISABLE KEYS */;
INSERT INTO `biz_book_chunk` (`id`, `book_id`, `chunk_no`, `chapter`, `content`, `char_count`, `vector_id`, `create_time`) VALUES (1,3,1,'第三章 地窖藏书','第一章 大观园奇遇\n这一年的春天，贾宝玉在大观园西侧的沁芳亭偶遇一位白发老者。老者自称时间旅人，赠予宝玉一枚刻着星纹的玉佩。\n第二章 星纹之谜\n那枚玉佩每逢午夜会浮现出蓝色星纹，指引宝玉前往园中一处从未有人到过的地窖。地窖里藏着三十七卷失传的古籍。\n第三章 地窖藏书\n宝玉与林黛玉一同进入地窖，发现古籍记载着大观园地下河的走向。黛玉据此绘制了一张水系图，取名《沁芳水系考》。',187,'book-3-1','2026-11-16 11:17:35'),(47,2,1,NULL,'用户贴了一段 Java 代码，问“什么意思”。这段代码看起来是 Spring AI 1.0 版本中 VectorStore 的用法，使用了 SearchRequest 构建器模式来构建搜索请求，然后调用 similaritySearch 返回 List<Document>。\n\n需要解释：\n\n整体作用：向量数据库相似度检索\n\nSearchRequest.builder() 各参数含义\n\n注释的含义（API 变化）\n\n返回的 List<Document> 是什么\n\n实际执行流程\n\n还要提到这是 Spring AI 的 API，旧版本 similaritySearch(String query, SearchRequest) 返回 List<Document>，而新版本有变化……需要仔细核对。实际上在 Spring AI 1.0.0-M6 之后，VectorStore.similaritySearch(SearchRequest) 返回 List<Document>。',437,'book-2-1','2026-11-16 18:51:45'),(48,2,2,NULL,'similaritySearch(SearchRequest) 返回 List<Document>。之前的 API 可能是 SearchRequest 配合 SearchResult 包装？还是说旧版本是 List<Document> similaritySearch(SearchRequest request)？\n\n我记得 Spring AI 的 VectorStore 接口：\n\nList<Document> similaritySearch(String query);\n\nList<Document> similaritySearch(SearchRequest request);\n\nList<Document> similaritySearch(SearchRequest request, ...)\n\n在较早版本（0.8.x）中，similaritySearch(SearchRequest) 返回 List<Document>。',423,'book-2-2','2026-11-16 18:51:45'),(49,2,3,NULL,'similaritySearch(SearchRequest) 返回 List<Document>。后来在 1.0.0-M 版本中是否改成了 SearchResult？实际上在 Spring AI 1.0.0-M6 中，VectorStore.similaritySearch 返回 List<Document>。在 1.0.0-M7 或 RC 中可能引入了 SearchResult？\n\n嗯，用户注释说“similaritySearch 直接返回 List<Document>，不再有 SearchResult 包装”，说明之前某个版本 similaritySearch 返回了 SearchResult（可能是 List<SearchResult> 或 SearchResult 包装），现在改回 List<Document>。这可能是 Spring AI 1.0.0 正式版的变化？需要谨慎，不要断言具体版本，只说“这是 Spring AI 的 VectorStore API，注释说明 API 有变化”。',456,'book-2-3','2026-11-16 18:51:45'),(50,2,4,NULL,'本，只说“这是 Spring AI 的 VectorStore API，注释说明 API 有变化”。\n\n实际上我记得 Spring AI 1.0.0 中 VectorStore 接口有：\n\njava\nList<Document> similaritySearch(SearchRequest request);\n而 SearchRequest 有 query、topK、similarityThreshold、filter 等字段。\n\n用户代码中的 .query(question) 说明 question 是 String，Spring AI 的 SearchRequest builder 确实有 query(String)。\n\n关于 topK(3)：返回最相似的 3 个文档。\nsimilarityThreshold(0.5)：相似度阈值，低于 0.5 的过滤掉。注意不同向量库相似度定义不同（余弦相似度 vs 距离），Spring AI 的 similarityThreshold 语义是“相似度得分高于阈值保留”，但具体实现因存储而异。',473,'book-2-4','2026-11-16 18:51:45'),(51,2,5,NULL,'的 similarityThreshold 语义是“相似度得分高于阈值保留”，但具体实现因存储而异。\n\nList<Document> documents：每个 Document 包含文本内容、元数据、可选的向量和得分。\n\n注释：“不再有 SearchResult 包装” —— 可能之前是 SearchResult 包含 List<Document> 和 Similarity 等信息？在 Spring AI 1.0.0-M8 左右，VectorStore.similaritySearch 返回 List<Document>，而 Document 中通过 getMetadata() 或 getScore() 获取相似度？实际上 Spring AI 的 Document 有 getScore()？我记得 Document 有 getMetadata()、getContent()、getFormattedContent()、getId()，没有 getScore()。',436,'book-2-5','2026-11-16 18:51:45'),(52,2,6,NULL,'ent()、getFormattedContent()、getId()，没有 getScore()。相似度分数在 Document 的 metadata 中？不，在 Spring AI 中，Document 有一个 score 字段（Double score），通过 getScore() 获取，但可能在某个版本中弃用。\n\n好吧，不要过度深入版本细节，重点解释语义和用法。\n\n回答结构：\n\n一句话总结：这是 Spring AI 向量数据库相似度检索的代码。\n\n逐行解释。\n\n解释 SearchRequest 三个参数。\n\n解释返回值 List<Document> 和注释含义。\n\n说明典型使用场景（RAG）。\n\n注意事项（阈值因存储而异、topK 等）。\n\n用中文回答，清晰明了。\n\n这段代码是 Spring AI 中调用向量数据库做相似度检索的典型写法，通常用在 RAG（检索增强生成）流程里：把用户问题转成向量，去向量库里找出最相关的几段文档。',424,'book-2-6','2026-11-16 18:51:45'),(53,2,7,NULL,'型写法，通常用在 RAG（检索增强生成）流程里：把用户问题转成向量，去向量库里找出最相关的几段文档。\n\n逐行解释：\n\njava\nSearchRequest searchRequest = SearchRequest.builder()\n        .query(question)          // 查询文本（用户问题），底层会先把它 embedding 成向量\n        .topK(3)                  // 最多返回 3 条最相似的文档\n        .similarityThreshold(0.5) // 相似度阈值：低于 0.5 的结果会被过滤掉\n        .build();                 // 构建出不可变的 SearchRequest 对象\nquery(question)：要检索的查询内容。注意这里传的是原始文本，VectorStore 内部会调用 EmbeddingModel 把 question 转成向量再去比对。\n\ntopK(3)：Top-K 检索，只取相似度最高的 3 条。',482,'book-2-7','2026-11-16 18:51:45'),(54,2,8,NULL,'question 转成向量再去比对。\n\ntopK(3)：Top-K 检索，只取相似度最高的 3 条。\n\nsimilarityThreshold(0.5)：相似度下限。具体“相似度”怎么算取决于底层向量库（余弦相似度、内积、欧氏距离等），Spring AI 会做归一化，但不同 store 的语义可能有细微差别，0.5 不一定在所有库里都等价。\n\nbuilder()：Spring AI 1.x 里 SearchRequest 改成了 builder 模式，参数多了以后可读性更好，也支持 filterExpression 等可选参数。\n\njava\nList<Document> documents = vectorStore.similaritySearch(searchRequest);\n调用向量库执行检索，返回命中的文档列表。',366,'book-2-8','2026-11-16 18:51:45'),(55,2,9,NULL,'ilaritySearch(searchRequest);\n调用向量库执行检索，返回命中的文档列表。\n\n注释里说的 “不再有 SearchResult 包装” 是指 API 的版本变化：早期/某些版本的 similaritySearch 返回值外面还包了一层 SearchResult（类似 SearchResult.getDocuments()），现在直接返回 List<Document>，用起来更直接。\n\n返回的每个 Document 一般包含：\n\ngetContent() / getText()：文档片段正文\n\ngetMetadata()：元数据（来源文件名、页码、chunk 序号等）\n\n可能还有相似度分数（不同版本/实现放在 score 或 metadata 里）\n\n整体语义：在向量库中找出与 question 最相似、且相似度 ≥ 0.5 的 3 个文档片段。拿到 documents 后，通常会把这些内容拼进 prompt，交给大模型生成最终答案，这就是 RAG 的“检索”环节。',450,'book-2-9','2026-11-16 18:51:45'),(56,2,10,NULL,'s 后，通常会把这些内容拼进 prompt，交给大模型生成最终答案，这就是 RAG 的“检索”环节。\n\n几个容易踩的点：\n\nsimilarityThreshold 设太高（如 0.9）可能一条都召回不到，设太低会引入噪声，需要根据 embedding 模型和向量库调。\n\ntopK 不是越大越好，太大反而稀释上下文、增加 token 成本。\n\n如果 question 是空串或 null，一般会抛异常或返回空列表，建议先做校验。\n\n这是 Spring AI 的 API，包名通常是 org.springframework.ai.vectorstore.SearchRequest 和 org.springframework.ai.document.Document，别和别的框架搞混。',342,'book-2-10','2026-11-16 18:51:45');
